const STORIES = [{"id": "STORY-CORDOBA", "title": "من الإمارة إلى الخلافة", "summary": "ثلاث محطات لقراءة تحوّل قرطبة: الربض، المدينة، ثم المدينة الخلافية الجديدة.", "period": "750–1031", "warning": "الخطوط بين المحطات تنظيم سردي لا طريق سفر.", "steps": [{"title": "شقندة قبل 818م", "text": "الحفر الواسع يقدم سجلًا مباشرًا للحياة اليومية والتخطيط الحضري في قرطبة الأموية المبكرة.", "place": "PLC-SAQUNDA", "claim": "RUR-CLM04"}, {"title": "قرطبة: المدينة والجامع", "text": "العقار التاريخي يربط النسيج الحضري بالجامع الكبير وتراكمات المدينة الإسلامية.", "place": "PLC-CORDOBA-WH", "claim": "ATLAS-CLM02"}, {"title": "مدينة الزهراء", "text": "مدينة جديدة للخلافة في القرن العاشر، مع بنية حضرية ومادية واسعة.", "place": "PLC-MADINAT-ZAHRA", "claim": "ATLAS-CLM01"}]}, {"id": "STORY-EAST", "title": "الشرق الأندلسي المبكر", "summary": "شواهد مادية من الفضاءات الدينية إلى الحصون والمجتمع الريفي.", "period": "8–13م", "warning": "المواقع مستقلة ولا تمثل إقليمًا سياسيًا واحدًا.", "steps": [{"title": "توسال دي لا فيلا", "text": "من أقدم الشواهد الأثرية للعمارة الدينية الإسلامية في شبه الجزيرة.", "place": "PLC-TOSSAL-VILA", "claim": "ARC-CLM01"}, {"title": "المولون", "text": "موقع ثانٍ يتيح مقارنة التكوين المبكر للفضاءات الدينية.", "place": "PLC-EL-MOLON", "claim": "ARC-CLM01"}, {"title": "بايرين", "text": "حصن ودليل نباتي مؤرخ؛ أولوية الدخن ما تزال حساسة للتحديث.", "place": "PLC-BAIREN", "claim": "ARC-CLM03"}, {"title": "خيريسة/شيريسا", "text": "التحليل العظمي يفتح نافذة على العمل والرعاية في مجتمع فلاحي.", "place": "PLC-XERESA", "claim": "RUR-CLM02"}]}, {"id": "STORY-KNOWLEDGE", "title": "شبكات المعرفة خارج الحدود", "summary": "غرناطة وطليطلة ودمشق بوصفها عقدًا مختلفة لانتقال الأشخاص والأعمال والترجمة.", "period": "11–13م", "warning": "ليس طريقًا واحدًا لشخص واحد إلا حيث يثبت Claim ذلك.", "steps": [{"title": "غرناطة", "text": "عقدة أندلسية في مسار انتقال أفراد وأعمال إلى المشرق.", "place": "PLC-GRANADA", "claim": "ARC-CLM09"}, {"title": "طليطلة", "text": "بيئة ترجمة عبر خلفيات دينية ولغوية متعددة.", "place": "PLC-TOLEDO", "claim": "SOC-CLM08"}, {"title": "دمشق", "text": "محطة شرقية في شبكة انتقال المعرفة؛ لا تُستكمل المحطات الوسيطة دون مصدر مباشر.", "place": "PLC-DAMASCUS", "claim": "ARC-CLM09"}]}, {"id": "STORY-SE-CITIES", "title": "المدينة والحرفة في الجنوب الشرقي", "summary": "من بَجّانة إلى ألمرية ثم غرناطة: إنتاج، ميناء، وعمران.", "period": "9–15م", "warning": "الترتيب تعليمي موضوعي وليس مسارًا زمنيًا متصلًا دائمًا.", "steps": [{"title": "بَجّانة", "text": "فرن خزف مزجج ثم حي بمساكن وشوارع ومحلات وورش.", "place": "PLC-PECHINA", "claim": "ARC-CLM04"}, {"title": "ألمرية", "text": "مرفأ ونسيج وحركة سلع ضمن اقتصاد متصل.", "place": "PLC-ALMARIYYA", "claim": "RUR-CLM03"}, {"title": "غرناطة النصرية", "text": "الحمراء والبيازين وجنة العريف كوحدة تراثية مركبة مع وظائف مختلفة.", "place": "PLC-ALHAMBRA-WH", "claim": "ATLAS-CLM03"}]}, {"id": "STORY-ZALLAQA", "title": "الزلاقة على مراحل", "summary": "ثماني محطات من سقوط طليطلة إلى عودة يوسف بن تاشفين إلى مراكش، كل محطة بشاهدها من المصادر الأولية.", "period": "478–479هـ / 1085–1086م", "warning": "الخطوط بين المحطات تنظيم سردي لا مسار سير مقيس؛ موضع بطحاء الزلاقة نفسها غير محدد في المصادر المستعملة والمرساة مدينة بطليوس؛ أعداد الجيوش تُعرض بمصادرها لا رقمًا واحدًا.", "steps": [{"title": "سقوط طليطلة 478هـ", "text": "أخذ الأذفونش طليطلة في محرم 478هـ بحسب ما نقله المقري عن ابن غلقمة، وكانت الزلاقة في السنة التي بعدها؛ ويقدّم ابن الأثير خبر الزلاقة بذكر ملك الفرنج طليطلة.", "place": "PLC-TOLEDO", "claim": "CLM-ZLQ-03"}, {"title": "مشايخ قرطبة يجتمعون على الاستنجاد", "text": "لما رأى مشايخ قرطبة وفقهاؤها قوة الفرنج واستعانة بعض ملوك الطوائف بهم اجتمعوا عند القاضي ابن أدهم، وانتهى رأيهم إلى الكتابة إلى يوسف بن تاشفين صاحب مراكش (ابن الأثير، ابن خلكان).", "place": "PLC-CORDOBA", "claim": "CLM-ZLQ-03"}, {"title": "الاستنجاد يبلغ أمير المسلمين بسبتة", "text": "كان أمير المسلمين بسبتة فأمر في الحال بعبور العساكر واستدعى من بقي بمراكش (ابن الأثير). اختلفت الروايات في الوسيلة: كتاب من المعتمد ثم وفد القاضي (ابن خلكان)، أو جواز المعتمد بنفسه إلى سبتة (ابن دحية).", "place": "PLC-CEUTA", "claim": "CLM-ZLQ-03"}, {"title": "العبور إلى الجزيرة الخضراء", "text": "عبرت العساكر إلى الجزيرة الخضراء المقابلة لسبتة، وعبر يوسف في آخرهم بعد تكاملهم (ابن خلكان)؛ ويذكر ابن الأثير العبور دون تسمية المرسى.", "place": "PLC-ALGECIRAS", "claim": "CLM-ZLQ-03"}, {"title": "الاجتماع بالمعتمد بإشبيلية", "text": "اجتمع أمير المسلمين بالمعتمد بإشبيلية، وخرج من أهل قرطبة عسكر كثير وقصده المتطوعة من سائر الأندلس (ابن الأثير، الذهبي).", "place": "PLC-SEVILLE", "claim": "CLM-ZLQ-03"}, {"title": "الأذفونش يخرج من طليطلة", "text": "لما وصلت الأخبار إلى الأذفونش جمع فرسانه وسار من طليطلة (ابن الأثير)؛ وعدد فرسانه أربعون ألفًا عند ابن خلكان ويجعل ابن الأثير الفرنج خمسين ألفًا، ولا يُعرض رقم واحد.", "place": "PLC-TOLEDO", "claim": "CLM-ZLQ-03"}, {"title": "الزلاقة: المعسكران ثم يوم الجمعة", "text": "نزل الجيشان متقابلين بأرض الزلاقة من بلد بطليوس. هاجم الأذفونش معسكر المعتمد بكرة الجمعة فثبت المعتمد، ووصل أمير المسلمين إلى خيام الفرنج فانهزموا، ونجا الأذفونش في قلة (ابن الأثير، الذهبي، ابن خلكان، المراكشي بتفاصيل مختلفة).", "place": "PLC-BADAJOZ", "claim": "CLM-ZLQ-04"}, {"title": "العودة", "text": "عاد المعتمد إلى إشبيلية، ورجع أمير المسلمين إلى الجزيرة الخضراء فعبر إلى سبتة وسار إلى مراكش (ابن الأثير).", "place": "PLC-ALGECIRAS", "claim": "CLM-ZLQ-03"}]}];
const MODULES = [{"id": "EDU-01", "title": "كيف نعرف؟ أدلة فتح الأندلس", "summary": "مدخل في نقد المصادر: لماذا لا نكتفي بالروايات الأدبية المتأخرة، وكيف تعمل العملات والأختام وSource Genealogy معًا.", "level": "تمهيدي", "minutes": 22, "period": "711–756", "objectives": ["يميز بين المصدر المعاصر والمتأخر", "يفهم قيمة الفلوس والأختام", "يكتشف الفرق بين الحدث والأسطورة"], "steps": [{"n": 1, "kind": "concept", "title": "قاعدة البداية", "text": "مصادر الفتح المكتوبة كثيرة الأهمية، لكن جزءًا مهمًا منها متأخر؛ لذلك نبدأ بالموازنة بين النص والمادة.", "claim": "CLM-010", "place": null, "hint": "افتح بطاقة Claim ثم اعرض أنواع الدليل."}, {"n": 2, "kind": "evidence", "title": "الفلوس والأختام", "text": "النقد والأختام لا تحكي القصة كاملة، لكنها تقدم قرائن معاصرة نسبيًا على الضم والجباية والتبادل.", "claim": "CLM-011", "place": null, "hint": "قارن بين Evidence مادي ورواية نصية."}, {"n": 3, "kind": "genealogy", "title": "من أين جاءت الرواية؟", "text": "Source Genealogy يمنعنا من معاملة كتاب متأخر كشاهد عيان، ويعيد كل خبر قدر الإمكان إلى طبقته المصدرية.", "claim": "CLM-018", "place": null, "hint": "أظهر سلسلة المصدر."}, {"n": 4, "kind": "myth", "title": "حرق السفن", "text": "الرواية مشهورة، لكن الشهرة ليست دليلًا. تُعرض هنا كقصة موضع شك لا كحقيقة ثابتة.", "claim": "CLM-002", "place": null, "hint": "زر: ما الذي يجعل الرواية Myth؟"}, {"n": 5, "kind": "person", "title": "من هو طارق؟ وماذا تقول أقدم رواية؟", "text": "أقدم رواية عربية باقية للفتح عند ابن عبد الحكم (ت 257هـ): طارق بن زياد مولى موسى بن نصير والي إفريقية، جاز البحر في مراكب يليان صاحب سبتة، ونزل جبلًا سُمي باسمه، وهزم لذريق بكورة شذونة. لاحظ أن الشهر وعدد الجيش مختلف فيهما في المصادر نفسها، وأن المنصة تعرض الخلاف لا رقمًا واحدًا.", "claim": "CLM-FTH-01", "place": "PLC-MEDINA-SIDONIA", "hint": "افتح الشواهد وقارن بين «وادي لكة» و«وادي أم حكيم» في تسمية موضع المعركة."}, {"n": 6, "kind": "politics", "title": "موسى يلحق بطارق", "text": "دخل موسى بن نصير الأندلس في رجب 93هـ فتلقاه طارق بقرطبة وقال له «إنما أنا مولاك، وهذا الفتح لك»، ثم خرج موسى بغنائمه مستخلفًا ابنه عبد العزيز، ووفد على الخليفة فنُكب. هذه الخطوة تربط الفتح بعصر الولاة الذي يبدأ بعبد العزيز.", "claim": "CLM-FTH-02", "place": "PLC-CORDOBA", "hint": "انتقل إلى وحدة «الدولة في الأندلس» لترى ما بعد استخلاف عبد العزيز."}]}, {"id": "EDU-02", "title": "قرطبة: من الربض إلى الخلافة", "summary": "مسار مكاني وزمني من شقندة إلى إعلان الخلافة ومدينة الزهراء والجامع الكبير.", "level": "متوسط", "minutes": 28, "period": "750–1031", "objectives": ["يربط التحول السياسي بالعمران", "يفهم وظيفة الدليل الأثري والنقدي", "يقرأ المكان عبر طبقات زمنية"], "steps": [{"n": 1, "kind": "place", "title": "شقندة قبل 818م", "text": "الحفر الواسع يفتح نافذة على الشوارع والمباني والحياة اليومية في قرطبة الأموية المبكرة.", "claim": "RUR-CLM04", "place": "PLC-SAQUNDA", "hint": "حدد الموقع على الخريطة."}, {"n": 2, "kind": "politics", "title": "929م: إعلان الخلافة", "text": "يتحول الادعاء السياسي إلى Claim قوي عندما يلتقي النص المؤرخ مع النقود المعاصرة.", "claim": "CLM-001", "place": "PLC-CORDOBA", "hint": "شغّل خط الزمن إلى 929."}, {"n": 3, "kind": "place", "title": "مدينة الزهراء", "text": "مدينة جديدة للخلافة في القرن العاشر، لا مجرد «قصر» منفرد؛ التخطيط والمياه والطرق جزء من الدليل.", "claim": "ATLAS-CLM01", "place": "PLC-MADINAT-ZAHRA", "hint": "انتقل إلى نقطة UNESCO."}, {"n": 4, "kind": "architecture", "title": "الجامع والمدينة", "text": "وسط قرطبة التاريخي يسمح بقراءة تراكمات المدينة والجامع الكبير عبر قرون.", "claim": "ATLAS-CLM02", "place": "PLC-CORDOBA-WH", "hint": "قارن المدينة بالمركز الخلافي الجديد."}]}, {"id": "EDU-03", "title": "الحياة اليومية: بيت وورشة وسوق وميناء", "summary": "تجربة تقرأ الحياة اليومية من بَجّانة وألمرية وشيريسا والعملات وكتب الطبخ بدل الاقتصار على تاريخ الأسر الحاكمة.", "level": "متوسط", "minutes": 30, "period": "9–13م", "objectives": ["يتعرف إلى مصادر الحياة اليومية", "يفصل بين النص والممارسة المادية", "يقارن الريف بالمدينة"], "steps": [{"n": 1, "kind": "craft", "title": "بَجّانة: من الفرن إلى الحي", "text": "فرن خزف مزجج من القرن التاسع يعقبه حي بمساكن وشوارع ومحلات وورش.", "claim": "ARC-CLM04", "place": "PLC-PECHINA", "hint": "فعّل طبقة الحرفة."}, {"n": 2, "kind": "urban", "title": "ألمرية: الميناء والنسيج", "text": "الموقع والمواد ومشروع GLOBALM يقدمون مدينة مرتبطة بالإنتاج والميناء وشبكات واسعة.", "claim": "RUR-CLM03", "place": "PLC-ALMARIYYA", "hint": "اعرض محور الاقتصاد."}, {"n": 3, "kind": "rural", "title": "شيريسا: العمل والرعاية", "text": "التحليل العظمي يتيح سؤالًا مختلفًا: كيف عاش الناس وعملوا ورعوا بعضهم؟", "claim": "RUR-CLM02", "place": "PLC-XERESA", "hint": "افتح Evidence الصحي/العظمي."}, {"n": 4, "kind": "text", "title": "كتب الطبخ", "text": "الوصفات مصدر ثمين، لكنها لا تمثل كل المجتمع أو كل الطبقات تلقائيًا.", "claim": "ARC-CLM07", "place": null, "hint": "قارن النص بالأثر."}, {"n": 5, "kind": "economy", "title": "النقد في الحياة اليومية", "text": "العملات ترتبط بالضرائب والجيش والتجارة والمعاملات، مع اختلاف كثافة الاستخدام عبر الزمن والمكان.", "claim": "SOC-CLM09", "place": null, "hint": "اربط النقد بمحاور الاقتصاد."}]}, {"id": "EDU-04", "title": "مجتمع متعدد… لا قالب واحد", "summary": "وحدة تفكك التبسيط الشائع لفكرة «الثقافات الثلاث» عبر الهوية والمادة والجندر واللغة.", "level": "متوسط", "minutes": 26, "period": "10–14م", "objectives": ["يتجنب تعميم convivencia", "يفهم حدود إسناد الهوية للقطعة", "يرى الاستثناءات دون تحويلها إلى قاعدة"], "steps": [{"n": 1, "kind": "concept", "title": "لا «جنة» ولا «صراع دائم»", "text": "العلاقات بين الجماعات تتغير حسب الزمن والمكان والسلطة والقانون؛ لا Narrative واحد يصلح لثمانية قرون.", "claim": "SOC-CLM01", "place": null, "hint": "اعرض حالات مختلفة بدل شعار واحد."}, {"n": 2, "kind": "method", "title": "هل للقطعة هوية دينية؟", "text": "الأسلوب وحده لا يكفي لنسبة قطعة إلى جماعة دينية؛ النقش والسياق أهم.", "claim": "SOC-CLM04", "place": null, "hint": "اختبار إسناد الهوية."}, {"n": 3, "kind": "person", "title": "صبح: استثناء موثق", "text": "وصول صبح إلى نفوذ سياسي كبير حالة موثقة مهمة، لكنها لا تتحول إلى وصف إحصائي لوضع النساء عامة.", "claim": "SOC-CLM06", "place": "PLC-CORDOBA", "hint": "بطاقة شخص/Claim."}, {"n": 4, "kind": "language", "title": "المشهد اللغوي", "text": "العربية والرومانسية الأندلسية والعبرية تؤدي أدوارًا مختلفة عبر الفترات والسياقات.", "claim": "CLM-003", "place": null, "hint": "اعرض طبقات اللغة بدل خريطة لغة واحدة."}]}, {"id": "EDU-05", "title": "شبكات المعرفة والامتداد", "summary": "من طليطلة وغرناطة إلى المشرق، ومن البلاطات إلى الحرف: كيف تنتقل النصوص والأشخاص والتقنيات بعد تغير السلطة.", "level": "متقدم", "minutes": 32, "period": "11–15م", "objectives": ["يميز بين طريق شخصي وشبكة معرفة", "يربط الترجمة بالسياق الاجتماعي", "يفهم الامتداد التقني والثقافي"], "steps": [{"n": 1, "kind": "translation", "title": "طليطلة والترجمة", "text": "التعاون بين مترجمين من خلفيات متعددة لا يلغي الخلافات حول المؤسسات والأسماء؛ لذلك نوثق عملًا بعمل.", "claim": "SOC-CLM08", "place": "PLC-TOLEDO", "hint": "اعرض عقدة ترجمة."}, {"n": 2, "kind": "network", "title": "الأندلس إلى المشرق", "text": "انتقال أشخاص ونصوص وأفكار يُبنى كمسارات موثقة، لا كخطوط سفر تخمينية.", "claim": "ARC-CLM09", "place": "PLC-DAMASCUS", "hint": "اعرض route مع تحذير التمثيل."}, {"n": 3, "kind": "legacy", "title": "ثقافة البلاط", "text": "بعض العناصر الأندلسية أصبحت جزءًا من ثقافات بلاط قشتالية، لا مجرد «نسخ» لحظي.", "claim": "SOC-CLM07", "place": "PLC-LEON", "hint": "فعّل Legacy."}, {"n": 4, "kind": "craft", "title": "مانيسس بعد تغير السلطة", "text": "استمرار تقنيات البريق المعدني يقدم مثالًا على بقاء الحرفة بعد تغير الإطار السياسي.", "claim": "SOC-CLM10", "place": "PLC-MANISES", "hint": "قارن الزمن السياسي بزمن التقنية."}]}, {"id": "EDU-06", "title": "إشبيلية: طبقات القصر والمئذنة", "summary": "وحدة قصيرة تقرأ القصر والجيرالدا بوصفهما طبقات أندلسية ثم مسارات إعادة استخدام وتحول معماري بعد 1248م.", "level": "تمهيدي", "minutes": 14, "period": "10–16م", "objectives": ["يتعرف إلى الطبقات المعمارية", "يفصل بين البقاء المادي واستمرار الوظيفة", "يفهم معنى إعادة الاستخدام"], "steps": [{"n": 1, "kind": "place", "title": "نواة القصر", "text": "تذكر UNESCO أن النواة الأصلية للقصر في إشبيلية شُيدت في القرن العاشر مقرًا للحاكم المسلم.", "claim": "ATLAS-CLM04", "place": "PLC-SEVILLE", "hint": "اذهب إلى إشبيلية."}, {"n": 2, "kind": "architecture", "title": "القصر الموحدي", "text": "بعض غرف وباحات وحدائق القصر الموحدي بقيت داخل مجمع أعيد بناؤه مرارًا.", "claim": "ATLAS-CLM04", "place": "PLC-SEVILLE", "hint": "فعّل طبقة heritage."}, {"n": 3, "kind": "architecture", "title": "الجيرالدا", "text": "كانت الجيرالدا مئذنة للمسجد، وتصفها UNESCO بأنها تحفة من العمارة الموحدية.", "claim": "ATLAS-CLM04", "place": "PLC-SEVILLE", "hint": "أظهر مفهوم reuse."}, {"n": 4, "kind": "concept", "title": "الاستمرار لا يعني الثبات", "text": "بقاء عنصر معماري لا يعني بقاء وظيفته أو سياقه السياسي؛ القراءة الصحيحة تتتبع التحول أيضًا.", "claim": "ATLAS-CLM04", "place": "PLC-SEVILLE", "hint": "سؤال انعكاسي."}]}, {"id": "EDU-07", "title": "الدولة في الأندلس: من الولاية إلى الخلافة", "summary": "وحدة تتبع تحول السلطة في الأندلس عبر ثلاثة أطوار موثقة: ولاية تابعة لإفريقية ودمشق، ثم إمارة أموية مستقلة بالخطبة دون ادعاء الخلافة، ثم خلافة معلنة سنة 316هـ انتهت بالفتنة سنة 422هـ. كل خطوة تفتح شواهدها، وحيث اختلفت المصادر يُعرض الخلاف كما هو.", "level": "متوسط", "minutes": 30, "period": "711–1031", "objectives": ["يميز بين الولاية والإمارة والخلافة بوصفها أطوارًا في شكل السلطة لا مجرد أسماء", "يقرأ كل تاريخ من شاهده ويعرف أن السنة الهجرية تُحوَّل تقريبًا", "يتعرف إلى بنية الدولة (الوزارة والحجابة والقضاء) من مصدرها", "يعرف كيف تسجل المنصة خلاف المصادر بدل حسمه بصمت"], "steps": [{"n": 1, "kind": "concept", "title": "ثلاثة أطوار لا ثلاثة أسماء", "text": "تنتظم دولة الأندلس في المصادر المعتمدة هنا في ثلاثة أطوار: ولاية تابعة بعد الفتح، ثم إمارة أموية ببيعة سنة 138هـ، ثم خلافة معلنة سنة 316هـ. الفرق بينها ليس في الاسم فقط بل في من يملك الخطبة والتعيين والألقاب. اقرأ الادعاء الأول لترى من كان الوالي يتبع.", "claim": "CLM-WUL-01", "place": null, "hint": "افتح الادعاء ولاحظ عبارة «تابعة لوالي إفريقية»."}, {"n": 2, "kind": "politics", "title": "ولاية تابعة: القيروان ثم دمشق", "text": "بعد فتح طارق في رمضان 92هـ حُكمت الأندلس ولايةً تابعة لوالي إفريقية الذي يتبع والي مصر، وعيّن الخليفة بعض الولاة مباشرة كالسمح. أول ولاتها عبد العزيز بن موسى بإشبيلية، وقُتل آخر 98هـ وقيل 97هـ.", "claim": "CLM-WUL-01", "place": "PLC-SEVILLE", "hint": "لاحظ أن سنة مقتل عبد العزيز مثبتة بروايتين، ولم تُختر واحدة بصمت."}, {"n": 3, "kind": "place", "title": "المقر ينتقل إلى قرطبة", "text": "انتقل مقر الولاية من إشبيلية إلى قرطبة نحو 98–99هـ. تنسب رواية ابن عذاري النقل إلى الحر بن عبد الرحمن الثقفي، ورواية ابن الأثير إلى أيوب بن حبيب؛ والمنصة تعرض الروايتين معًا.", "claim": "CLM-WUL-01", "place": "PLC-CORDOBA", "hint": "افتح الأطلس على قرطبة ثم عد إلى الشواهد لترى الروايتين."}, {"n": 4, "kind": "politics", "title": "ولاة كثيرون في أربعين سنة", "text": "تعاقب على الأندلس في نحو أربعين سنة ولاةٌ كثيرون قصيرو المدة، من أيوب بن حبيب والحر والسمح إلى عقبة بن الحجاج وبلج وأبي الخطار ويوسف الفهري. قائمة ابن عذاري مؤرخة، وقائمة ابن القوطية أقصر ومختلفة الترتيب، ولذلك لا تُعرض قائمة واحدة على أنها القائمة.", "claim": "CLM-WUL-02", "place": null, "hint": "قارن بين شاهد البيان المغرب وشاهد ابن القوطية في الادعاء نفسه."}, {"n": 5, "kind": "politics", "title": "أجناد الشام والعصبية", "text": "أنزل أبو الخطار سنة 125هـ أجناد الشام في كور الأندلس على أموال أهل الذمة: دمشق بإلبيرة، والأردن برية، وفلسطين بشذونة، وحمص بإشبيلية، وقنسرين بجيان، ومصر بباجة وتدمير. ثم غلبت العصبية بين اليمنية والمضرية فصار الأمر ليوسف الفهري اسمًا وللصميل تدبيرًا.", "claim": "CLM-WUL-03", "place": null, "hint": "ابحث في الأطلس عن إلبيرة وجيان لترى توزيع الأجناد."}, {"n": 6, "kind": "person", "title": "الداخل: بيعة الأضحى 138هـ", "text": "قامت الإمارة الأموية ببيعة عبد الرحمن بن معاوية الداخل بقرطبة يوم الأضحى 138هـ (نحو 15 مايو 756م) بعد هزيمة الوالي يوسف الفهري بالمصارة. وهو أموي من ولد هشام بن عبد الملك، وُلد بالشام سنة 113هـ، ومكان مولده مختلف فيه بين دمشق وتدمر.", "claim": "CLM-EMR-01", "place": "PLC-CORDOBA", "hint": "افتح بطاقة عبد الرحمن الداخل ثم شواهد التأسيس."}, {"n": 7, "kind": "politics", "title": "أمير لا خليفة", "text": "خوطب حكام الإمارة بـ«الأمير» ولم يتسمّوا بالخلافة ولا بإمرة المؤمنين. وقطع عبد الرحمن الداخل الدعاء للخليفة العباسي سنة 139هـ فاستقلت الإمارة بالخطبة، وبقي الحال كذلك حتى تسمّى عبد الرحمن بن محمد بأمير المؤمنين سنة 316هـ.", "claim": "CLM-EMR-02", "place": null, "hint": "اسأل نفسك: ما الذي يجعل دولة مستقلة دون أن تدّعي الخلافة؟"}, {"n": 8, "kind": "method", "title": "بنية الدولة وتسلسل الأمراء", "text": "تعاقب على الإمارة سبعة أمراء من بيت واحد: عبد الرحمن الداخل، هشام، الحكم، عبد الرحمن، محمد، المنذر، عبد الله، ثم حفيد عبد الله عبد الرحمن الناصر. وكان للداخل وزراء وحجّاب وقضاة، فبنية الدولة: الوزارة والحجابة والقضاء. هذه البنية مأخوذة من شاهد يعدّ الوزراء والحجاب والقضاة بأسمائهم.", "claim": "CLM-EMR-03", "place": null, "hint": "افتح الشاهد الذي يعدّ الوزراء الأربعة والحجّاب الخمسة."}, {"n": 9, "kind": "politics", "title": "316هـ: أمير المؤمنين الناصر لدين الله", "text": "في مستهل ذي الحجة 316هـ (نحو 15/16 يناير 929م) أمر عبد الرحمن بن محمد أن يُخاطَب بأمير المؤمنين وتلقب بالناصر لدين الله، محتجًّا بضعف العباسيين وظهور العبيديين. النقود المعاصرة تظهر التحول في الألقاب أيضًا.", "claim": "CLM-CAL-01", "place": "PLC-CORDOBA", "hint": "قارن بين هذا الادعاء والادعاء المرقّم CLM-001 من الحزمة الأصلية: المصدر النصي والنقود معًا."}, {"n": 10, "kind": "place", "title": "الزهراء مقرًّا للخلافة", "text": "ابتدأ الناصر بناء مدينة الزهراء سنة 325هـ مقرًّا للخلافة قرب قرطبة، ثم دُمّرت في حرب الفتنة سنة 1009–1010م، ويحفظ الموقع بنية حضرية تشمل الطرق والجسور والمياه والمباني.", "claim": "ATLAS-CLM01", "place": "PLC-MADINAT-ZAHRA", "hint": "افتح الأطلس على مدينة الزهراء، ولاحظ أن الإحداثية مرجع للعقار لا حدًّا."}, {"n": 11, "kind": "politics", "title": "الحجابة والفتنة والنهاية 422هـ", "text": "استبد الحاجب المنصور ابن أبي عامر بتدبير الدولة في خلافة هشام المؤيد الذي بويع صبيًّا. ثم بدأت الفتنة بخلع المؤيد وبيعة المهدي سنة 399هـ (1009م)، وتعاقب خلفاء أمويون وحموديون خُلع بعضهم ورُدّ، حتى خُلع هشام المعتد آخرهم وتولى ابن جهور أمر قرطبة في ذي الحجة 422هـ (ديسمبر 1031م). ترتيب خلفاء الفتنة الداخلي مسجل بثقة متوسطة.", "claim": "CLM-CAL-02", "place": "PLC-CORDOBA", "hint": "لاحظ علامة الخلاف على الادعاء: تواريخ كل خليفة من خلفاء الفتنة تنتظر إسنادات مستقلة."}]}, {"id": "EDU-08", "title": "الأندلس على الخريطة", "summary": "وحدة قصيرة تقرأ جزيرة الأندلس كما وصفها الجغرافيون العرب: اسمها، وموقعها في الأقاليم، وشكلها المثلث وبحارها الثلاثة وأركانها، والزقاق الذي يفصلها عن المغرب، وقواعدها الأربع، وثغورها. كل خطوة مربوطة بادعاء موثق من الروض المعطار وابن حزم، والمقادير مقادير القدماء لا قياسات حديثة.", "level": "تمهيدي", "minutes": 15, "period": "جغرافيا", "objectives": ["يتعرف إلى اسم الأندلس وأصوله المروية", "يحدد موقع الجزيرة وشكلها وبحارها على الخريطة", "يميز مقادير الجغرافيين القدماء من القياسات الحديثة", "يربط القواعد والثغور بالأحداث السياسية"], "steps": [{"n": 1, "kind": "place", "title": "ما اسم هذه الجزيرة؟", "text": "نقل الحميري أن اسم الأندلس في اليونانية «اشبانيا»، وقيل كان اسمها ابارية ثم باطقة ثم اشبانية من اسم ملك قديم اسمه اشبان، ثم سُميت الأندلس من أسماء الأندليش الذين سكنوها؛ ويقال إن اشبانية اسم خاص ببلد إشبيلية. هذه روايات ينقلها الجغرافي بصيغة «قيل» ولا يُقطع بأصل الاسم.", "claim": "CLM-GEO-01", "place": "PLC-SEVILLE", "hint": "افتح لوحة «كيف نعرف هذا؟» لترى نصوص الروض المعطار."}, {"n": 2, "kind": "place", "title": "أين تقع في أقاليم القدماء؟", "text": "جعلها الرازي في آخر الإقليم الرابع إلى المغرب، وجعل صاعد معظمها في الإقليم الخامس وجانبًا منها في الرابع كإشبيلية ومالقة وقرطبة وغرناطة والمرية ومرسية؛ وهي آخر المعمور في المغرب لأنها تتصل بالبحر المحيط الذي لا عمارة وراءه.", "claim": "CLM-GEO-01", "place": "PLC-CORDOBA", "hint": "قارن مواضع المدن الست على الخريطة العامة."}, {"n": 3, "kind": "place", "title": "جزيرة مثلثة تحيط بها ثلاثة بحار", "text": "سُميت جزيرة لأنها مثلثة الشكل يحيط بها البحر من ثلاث جهات: البحر الشامي جنوبًا، والبحر المظلم المحيط غربًا، وبحر الروم شمالًا؛ تضيق من الشرق حتى خمسة أيام بين البحرين، ورأسها العريض نحو سبعة عشر يومًا، وطولها ألف ومائة ميل وعرضها ستمائة ميل. هذه مقادير الجغرافيين القدماء لا قياسات حديثة.", "claim": "CLM-GEO-02", "place": "PLC-AL-ANDALUS", "hint": "ارسم المثلث ذهنيًا: أين تقع كل مدينة تعرفها على أضلاعه؟"}, {"n": 4, "kind": "place", "title": "الأركان الثلاثة", "text": "أركانها الثلاثة عند الحميري: موضع صنم قادس في الجنوب الغربي، والركن الشرقي بين نربونة وبرذيل بإزاء جزيرتي ميورقة ومنورقة، والركن الشمالي الغربي حيث ينعطف البحر عند المنارة في الجبل المشرف على البحر.", "claim": "CLM-GEO-02", "place": "PLC-PALMA", "hint": "حدد الجزائر الشرقية على الخريطة ثم ابحث عن دانية قبالتها."}, {"n": 5, "kind": "place", "title": "الزقاق: باب الأندلس", "text": "بحر الزقاق هو الداخل من البحر المحيط عند سبتة، يضيق بين طنجة والجزيرة الخضراء ثم يتسع ويتصل ببحر الروم. عرضه عند أضيقه مختلف فيه: ثلاثة أميال في نص الروض المعطار، واثنا عشر ميلًا عند ابن حزم، وثمانية عشر في نسخة أخرى؛ ولذلك يُعرض الخلاف كما هو.", "claim": "CLM-GEO-02", "place": "PLC-ALGECIRAS", "hint": "افتح صفحة الجزيرة الخضراء وسبتة، ثم عد إلى وحدة أدلة الفتح لترى عبور طارق."}, {"n": 6, "kind": "place", "title": "القواعد الأربع وقرطبة أم المدائن", "text": "كان ملوك الأعاجم قبل الفتح يتداولون السكنى بأربع مدن: إشبيلية وماردة وقرطبة وطليطلة؛ ثم صارت قرطبة قاعدة الأندلس وأم مدائنها ومستقر خلافة الأمويين.", "claim": "CLM-GEO-03", "place": "PLC-CORDOBA", "hint": "انتقل إلى وحدة «الدولة في الأندلس» لترى كيف صارت قرطبة عاصمة."}, {"n": 7, "kind": "place", "title": "دار جهاد وثغور", "text": "وصف الحميري الأندلس بأنها دار جهاد وموطن رباط أحاط بشرقيها وشمالها وبعض غربها أهل الكفر؛ ومن هنا جاءت تسمية الثغور التي ستتكرر في أخبار الولاة والأمراء والطوائف.", "claim": "CLM-GEO-03", "place": "PLC-TOLEDO", "hint": "لاحظ مواضع طليطلة وسرقسطة وبطليوس بالنسبة إلى الشمال."}]}, {"id": "EDU-09", "title": "من المرابطين إلى غرناطة: دولتان بربريتان وبنو نصر", "summary": "تتبع الوحدة الأندلس بعد الطوائف: المرابطون من ضم الطوائف 484هـ إلى آخر دعوتهم، وعبور الموحدين وتسلسل خلفائهم، ووقعتا الأرك 591هـ والعقاب 609هـ، ثم قيام الدولة النصرية ببيعة أرجونة 629هـ وصمودها بالهدنة. كل خطوة مبنية على ادعاء موثق من المعجب والكامل وتاريخ الإسلام والتكملة والإحاطة، والخلاف في الأيام والسنين معروض لا مُرجَّح.", "level": "متوسط", "minutes": 25, "period": "1091–1492", "objectives": ["يرتب أمراء المرابطين وخلفاء الموحدين الذين حكموا الأندلس", "يميز الأرك (نصر) من العقاب (هزيمة) ويعرف تاريخ كل منهما", "يشرح كيف يُثبت الخلاف في يوم الوقعة أو شهر الوفاة", "يربط بيعة أرجونة 629هـ بقيام الدولة النصرية وصمودها"], "steps": [{"n": 1, "kind": "concept", "title": "ثلاث دول بعد الطوائف", "text": "بعد سقوط دول الطوائف سنة 484هـ تعاقب على الأندلس ثلاث قوى: المرابطون من المغرب الأقصى، ثم الموحدون، ثم مملكة غرناطة النصرية التي بقيت وحدها حتى 897هـ. هذه الوحدة تتبع الدولتين البربريتين ثم قيام بني نصر.", "claim": "CLM-MRB-01", "place": null, "hint": "قارن هذا الترتيب بالعصور في الخط الزمني."}, {"n": 2, "kind": "person", "title": "يوسف بن تاشفين: من الزلاقة إلى ضم الطوائف", "text": "بعد الزلاقة 479هـ ضم أمير المسلمين يوسف بن تاشفين الأندلس إلى ملكه سنة 484هـ، وبقي على ملكه إلى أن توفي سنة 500هـ وملك بعده ابنه علي وتلقب أمير المسلمين.", "claim": "CLM-MRB-01", "place": "PLC-SEVILLE", "hint": "افتح قصة «الزلاقة على مراحل» في الأطلس."}, {"n": 3, "kind": "politics", "title": "علي وتاشفين: ضعف أمر الملثمين", "text": "توفي علي بن يوسف في 7 رجب 537هـ وعُهد إلى ابنه تاشفين، الذي توفي سنة 539هـ عند ابن الأثير و540هـ عند الذهبي؛ وبموتهما ضعف أمر الملثمين وقوي عبد المؤمن. لاحظ أن المنصة تعرض السنتين ولا ترجّح.", "claim": "CLM-MRB-01", "place": null, "hint": "اقرأ الشاهدين المتعارضين في سجل تاشفين."}, {"n": 4, "kind": "place", "title": "ثوار مغرب الأندلس: ابن قسي بمرتلة", "text": "في آخر دعوة المرابطين قام دعاة بمغرب الأندلس، منهم أحمد بن قسي الذي ادعى الولاية ثم الهداية وقام بحصن مرتلة، فأسلمه أصحابه وأخذه الموحدون إلى عبد المؤمن فعفا عنه. سنة قيامه لم تُتحقق من نص صريح.", "claim": "CLM-MRB-01", "place": "PLC-013", "hint": "حدد مرتلة على الخريطة غرب الأندلس."}, {"n": 5, "kind": "place", "title": "عبور الموحدين: جبل الفتح وبيعة الوجوه", "text": "دخل غرب الأندلس في ملك الموحدين على يد أبي حفص عمر إينتي، ثم عبر عبد المؤمن من سبتة ونزل جبل طارق وسماه جبل الفتح وأقام به أشهرًا، ووفدت عليه وجوه مالقة وغرناطة ورندة وقرطبة وإشبيلية للبيعة.", "claim": "CLM-MWH-01", "place": "PLC-CEUTA", "hint": "تتبع المسار: سبتة ← جبل الفتح ← إشبيلية."}, {"n": 6, "kind": "politics", "title": "خلفاء الموحدين الخمسة", "text": "عبد المؤمن (ت 558هـ بسلا) ← يوسف أبو يعقوب (طُعن على شنترين ومات 7 رجب 580هـ) ← يعقوب المنصور (ت 595هـ) ← محمد الناصر (ت 10 شعبان 610هـ) ← يوسف المستنصر (بويع 11 شعبان 610هـ وتوفي 620هـ). في يوم وفاة عبد المؤمن وشهر وفاة المنصور خلاف بين المعجب والكامل معروض في السجلات.", "claim": "CLM-MWH-01", "place": null, "hint": "افتح سجل الدولة الموحدية لترى مدد الولاية."}, {"n": 7, "kind": "politics", "title": "الأرك 591هـ: نصر بيوم مختلف فيه", "text": "عبر المنصور في جمادى الآخرة 591هـ وانتصر على الأدفنش في وقعة الأرك يوم الأربعاء من شعبان: الثالث عند المراكشي والتاسع عند ابن الأبار. لم ينجُ الأدفنش إلا في نحو ثلاثين من قواده، ثم هادنه المنصور عشر سنين.", "claim": "CLM-MWH-02", "place": null, "hint": "لاحظ كيف يظهر الخلاف في اليوم دون الشهر والسنة."}, {"n": 8, "kind": "politics", "title": "العقاب 609هـ: هزيمة الموحدين وأسبابها", "text": "خرج الناصر من إشبيلية أول سنة 609هـ ونزل جيان، ثم دهمه الأدفنش بالعقاب قرب حصن سالم يوم الاثنين منتصف صفر فانهزم الموحدون وقُتل منهم خلق كثير. يعزو المراكشي الهزيمة إلى اختلاف قلوب الموحدين لتأخر العطاء.", "claim": "CLM-MWH-02", "place": "PLC-JAEN", "hint": "قارن بين رواية المعجب وما نقله الذهبي."}, {"n": 9, "kind": "person", "title": "ابن الأحمر: بيعة أرجونة 629هـ", "text": "بويع محمد بن يوسف بن نصر، الغالب بالله، بأرجونة سنة 629هـ وتملك جيان، وملك إشبيلية نحو ثلاثين يومًا وقرطبة أيامًا ثم عادتا إلى ابن هود؛ ودخل غرناطة سنة 635هـ.", "claim": "CLM-NSR-01", "place": "PLC-JAEN", "hint": "أرجونة بليدة قرب قرطبة؛ ابحث عنها بين جيان وقرطبة."}, {"n": 10, "kind": "method", "title": "الهدنة والصمود: 642 أم 643؟", "text": "يقول الذهبي إن الهدنة عُقدت عام 642هـ ودامت عشرين سنة فعُمرت البلاد، بينما سجل معاهدة جيان في المنصة يحسمها في 643هـ. المنصة تُثبت الرقمين وتشير إلى أن الحسم يحتاج مقابلة الإحاطة واللمحة البدرية.", "claim": "CLM-NSR-01", "place": "PLC-GRANADA", "hint": "افتح سجل معاهدة جيان وقارن الإسنادين."}]}, {"id": "EDU-10", "title": "ملوك الطوائف: حين تفرّقت الأندلس", "summary": "بعد انقطاع خلافة قرطبة سنة 422هـ اقتسم رؤساء الأطراف الأندلس فصاروا مثل ملوك الطوائف: بنو جهور بقرطبة، وبنو عباد بإشبيلية، وبنو الأفطس ببطليوس، وبنو ذي النون بطليطلة، وبنو هود بسرقسطة، ومجاهد بدانية، وبنو صمادح بالمرية؛ ثم سقطت طليطلة 478هـ فاستُنجد المرابطون فأنهوا الطوائف الأولى 484هـ، ثم قامت طائفة ثانية بشرق الأندلس (بنو مردنيش) قاومت الموحدين حتى 567هـ. كل خطوة مبنية على ادعاء موثق من الكامل والحلة السيراء والذخيرة وجذوة المقتبس والمعجب، والخلاف في السنين معروض لا مُرجَّح.", "level": "متوسط", "minutes": 25, "period": "1031–1172", "objectives": ["يعدّد أبرز دول الطوائف الأولى وعواصمها وأسرها الحاكمة", "يربط سقوط طليطلة 478هـ باستنجاد المرابطين ونهاية الطوائف 484هـ", "يميّز الطوائف الثانية (بنو مردنيش) من الأولى", "يقرأ كيف تُثبت المنصة الخلاف في السنين ولا ترجّح"], "steps": [{"n": 1, "kind": "concept", "title": "كيف تفرّقت الأندلس", "text": "بعد انقطاع الدعوة الأموية من قرطبة سنة 422هـ اقتسم أصحاب الأطراف والرؤساء الأندلس، فتغلب كل إنسان على ناحية وصاروا مثل ملوك الطوائف، ولم يكن لهم اجتماع.", "claim": "CLM-TAI-01", "place": null, "hint": "قارن هذا التفرّق بوحدة الخلافة قبله."}, {"n": 2, "kind": "person", "title": "بنو جهور بقرطبة", "text": "استولى على قرطبة الوزير أبو الحزم بن جهور سنة 422هـ فدبّرها دون أن يتسمى بالإمارة (ت 435هـ)، ثم ابنه أبو الوليد محمد؛ وبعده غلب المأمون بن ذي النون على قرطبة سنة 467هـ.", "claim": "CLM-TAI-01", "place": "PLC-CORDOBA", "hint": "لاحظ أن بني جهور دبّروا قرطبة بلا لقب ملك."}, {"n": 3, "kind": "person", "title": "بنو عباد بإشبيلية", "text": "استقل القاضي ابن عباد بإشبيلية بعد خروج البربر عن قرطبة (ت 433هـ)، ثم ابنه المعتضد (ت 461هـ) الذي وسّع الملك، ثم المعتمد الذي ملك قرطبة وصار أعظم ملوك الطوائف شوكة.", "claim": "CLM-TAI-01", "place": "PLC-SEVILLE", "hint": "تتبّع توسّع بني عباد من إشبيلية إلى قرطبة."}, {"n": 4, "kind": "person", "title": "بنو ذي النون بطليطلة وبنو الأفطس ببطليوس", "text": "بطليطلة إسماعيل الظافر (ت 435هـ) ثم المأمون (ملك بلنسية وقرطبة) ثم القادر؛ وببطليوس المظفر بن الأفطس (ت 460هـ) ثم المنصور يحيى ثم المتوكل عمر الذي قُتل هو وابناه عند سقوط بطليوس 487هـ.", "claim": "CLM-TAI-01", "place": "PLC-TOLEDO", "hint": "حدّد طليطلة وبطليوس على الحد الغربي والأوسط."}, {"n": 5, "kind": "place", "title": "بنو هود ومجاهد وبنو صمادح", "text": "بسرقسطة سليمان بن هود (431–438هـ) وبنوه المقتدر؛ وبدانية والجزائر الموفق مجاهد العامري (غزا سردانية 406/407هـ، ت 436هـ)؛ وبالمرية خيران ثم زهير العامريان ثم بنو صمادح إلى 484هـ.", "claim": "CLM-TAI-01", "place": "PLC-008", "hint": "دانية والمرية وسرقسطة أطراف شرقية وشمالية."}, {"n": 6, "kind": "politics", "title": "سقوط طليطلة 478هـ", "text": "سقطت طليطلة في يد الأذفونش سنة 478هـ (وعند ابن الأثير في موضع 477هـ) بعد حصار شديد وكانت للقادر بن ذي النون؛ فكان ذلك مقدمة استنجاد أهل الأندلس بالمرابطين.", "claim": "CLM-TAI-02", "place": "PLC-TOLEDO", "hint": "اربط هذه الخطوة بوقعة الزلاقة في وحدة أخرى."}, {"n": 7, "kind": "politics", "title": "نهاية الطوائف الأولى 484هـ", "text": "في سنة 484هـ أُخذت إشبيلية من المعتمد وحُبس بأغمات، وماتت المرية إلى المرابطين بعد المعتصم بن صمادح، ومُلكت غرناطة في رجب 484هـ، فانقرضت دول الطوائف وصارت الأندلس ليوسف بن تاشفين.", "claim": "CLM-TAI-02", "place": "PLC-GRANADA", "hint": "نهاية الطوائف الأولى بداية عصر المرابطين."}, {"n": 8, "kind": "politics", "title": "الطوائف الثانية: بنو مردنيش بشرق الأندلس", "text": "لما ضعف المرابطون قامت دولة ثانية بمرسية وبلنسية: قدّم أهلها الزاهد ابن عياض ثم خادمه ابن مردنيش، فتحالف مع الفرنج وقاوم الموحدين، وأخذ صهره ابن همشك غرناطة سنة 557هـ ثم استردوها؛ ودام إلى وفاته 567هـ فدخل بنوه في طاعة الموحدين.", "claim": "CLM-TAI-03", "place": "PLC-MURCIA", "hint": "الطوائف الثانية جسر بين المرابطين والموحدين."}]}, {"id": "EDU-11", "title": "مملكة غرناطة النصرية: النشأة والصمود والحكّام", "summary": "آخر دول الإسلام بالأندلس: قامت على يد محمد الأول ابن الأحمر ببيعته بأرجونة 629هـ ثم دخوله غرناطة 635هـ، وصمدت نحو قرنين ونصف بمنعة الجبال والحصون والمهادنة، تجاوزت منافسة ابن هود في نشأتها واضطراب حكّامها الأواسط (محمد الثالث فنصر فإسماعيل الأول فمحمد الرابع). كل خطوة مبنية على ادعاء موثق قائم في المنصة (بيعة أرجونة وسلسلة الأواسط وابن هود) من الإحاطة لابن الخطيب وتاريخ الإسلام للذهبي، لا على مصدر جديد؛ وحدود الحكّام المتأخرين (بعد محمد الخامس) لم تُدرَج لعدم توفّر مصدر أولي منزَّل بها.", "level": "متوسط", "minutes": 18, "period": "1232–1492", "objectives": ["يربط نشأة الدولة النصرية ببيعة أرجونة 629هـ ودخول غرناطة 635هـ", "يفسّر صمود غرناطة قرنين ونصف بالمنعة الجبلية والحصون والمهادنة (رواية تُعرض بتنبيه)", "يتعرّف منافس النشأة ابن هود وكيف خلا الجوّ لابن الأحمر بهلاكه 635هـ", "يتتبّع اضطراب حكّام الأواسط الأربعة (خلع واغتيال) واكتمال التسلسل من محمد الأول إلى يوسف الأول"], "steps": [{"n": 1, "kind": "concept", "title": "نشأة الدولة: بيعةٌ ثم عاصمة", "text": "قامت آخر دول الإسلام بالأندلس على يد أبي عبد الله محمد بن يوسف بن نصر (محمد الأول ابن الأحمر): بويع بأرجونة سنة 629هـ، ثم دخل غرناطة سنة 635هـ فاتخذها عاصمةً لملكٍ سيمتدّ نحو قرنين ونصف. (ادعاء بيعة أرجونة موثّق من الإحاطة والذهبي.)", "claim": "CLM-NSR-01", "place": "PLC-GRANADA", "hint": "البيعة أولًا في أرجونة، ثم انتقلت العاصمة إلى غرناطة."}, {"n": 2, "kind": "person", "title": "منافس النشأة: ابن هود", "text": "لم تخلُ النشأة من منافس؛ فقد توثّب محمد بن يوسف بن هود الجذامي على الموحدين ودعا لبني العباس واستولى على أكثر الأندلس، لكن ابن الأحمر هزمه ثلاث مرات، فلما هلك بالمرية سنة 635هـ — وهي عام دخول ابن الأحمر غرناطة — خلا الجوّ للنصريين. (موثّق من تاريخ الإسلام.)", "claim": "CLM-NSR-01", "place": null, "hint": "هلاك ابن هود 635هـ هو عام دخول غرناطة نفسه."}, {"n": 3, "kind": "concept", "title": "لماذا صمدت غرناطة؟", "text": "تفسِّر المصادر طول بقاء غرناطة بمنعة موقعها الجبلي وكثرة حصونها وسياسة المهادنة مع جيرانها. (هذه رواية معروضة بتنبيه «موثّقة جزئيًا» لأنها استنتاج المؤرّخ لا نصّ صريح مؤرَّخ.)", "claim": "CLM-NSR-01", "place": "PLC-GRANADA", "hint": "الجبال والحصون والمهادنة: ثلاثة أسباب للصمود، لا سبب واحد."}, {"n": 4, "kind": "politics", "title": "أزمة الأواسط (1): محمد الثالث المخلوع", "text": "بعد جيل التأسيس اضطرب الحكم: محمد الثالث (ثالث الملوك) ضعف بصره حتى عمي وأُقعد، فخُلع يوم عيد الفطر 708هـ إذ وثب عليه أخوه، ثم اغتيل غريقًا لاحقًا. (موثّق من الإحاطة؛ وسنة وفاته متعارضة 710/713هـ فلا تُرجَّح.)", "claim": "CLM-NSR-01", "place": "PLC-GRANADA", "hint": "أول حلقات الاضطراب: خلعٌ لسلطان أعمى مقعد."}, {"n": 5, "kind": "politics", "title": "أزمة الأواسط (2): أبو الجيوش نصر", "text": "تولّى أبو الجيوش نصر بخلع أخيه محمد الثالث سنة 708هـ، لكنه غُلب في فتنة الرئيس أبي سعيد فرج وابنه إسماعيل، فخرج مخلوعًا إلى مدينة وادي آش ليلة 28 شوال 713هـ. (موثّق من الإحاطة.)", "claim": "CLM-NSR-01", "place": "PLC-GRANADA", "hint": "الخلع يتكرّر: نصر يُخلع إلى وادي آش."}, {"n": 6, "kind": "politics", "title": "أزمة الأواسط (3): إسماعيل الأول", "text": "بويع إسماعيل الأول (أبو الوليد) 27 شوال 713هـ، وهو حفيد محمد الثاني لأمه؛ وانتصر على النصارى في وقيعة المرج بظاهر غرناطة، لكنه استُشهد قتيلًا 26 رجب 725هـ على يد ابن عمه محمد بن إسماعيل «صاحب الجزيرة». (موثّق من الإحاطة، بلوح قبره.)", "claim": "CLM-NSR-01", "place": "PLC-GRANADA", "hint": "من الخلع إلى الاغتيال: إسماعيل يُقتل بيد ابن عمّه."}, {"n": 7, "kind": "politics", "title": "أزمة الأواسط (4): محمد الرابع", "text": "أُخذت البيعة لمحمد الرابع يوم مقتل أبيه (27 رجب 725هـ) وهو غلام لم يبقل خدّه؛ ومن أعظم مناقبه تخليص جبل الفتح، لكنه قُتل غيلةً في كمين قربه ضحوة 13 ذي الحجة 733هـ، فبويع أخوه أبو الحجاج يوسف الأول. (موثّق من الإحاطة.)", "claim": "CLM-NSR-01", "place": "PLC-GRANADA", "hint": "طفلٌ سلطان يخلّص جبل الفتح ثم يُقتل غيلةً."}, {"n": 8, "kind": "concept", "title": "خلاصة: سلسلة متصلة ودولة معمّرة", "text": "باكتمال حكّام الأواسط صار تسلسل سلاطين غرناطة متصلًا بلا فجوة من محمد الأول (635هـ) إلى يوسف الأول (733هـ) فمحمد الخامس؛ ورغم الخلع والاغتيال المتكرّر بقيت الدولة النصرية قائمةً نحو قرنين ونصف حتى 897هـ/1492م. (حكّامها بعد محمد الخامس لم يُدرَجوا بعدُ لعدم توفّر مصدر أولي منزَّل بتواريخهم.)", "claim": "CLM-NSR-01", "place": "PLC-GRANADA", "hint": "الاضطراب الداخلي لم يُسقط الدولة؛ عاشت أطول ممّا يُظنّ."}]}];
const QUIZ = [{"id": "Q-001", "module": "EDU-01", "type": "mcq", "prompt": "أي نوع من الأدلة يفيد مباشرة في دراسة الجباية والضم المبكر؟", "choices": ["كتب طبخ القرن 13", "الأختام/precintos والفلوس", "عمارة مانيسس", "قصر الحمراء"], "correct": 1, "explanation": "الفلوس والأختام من أهم الأدلة المادية للقرنين 8–9، ويمكن أن تقدم قرائن على الجباية والضم والتبادل.", "claim": "CLM-011", "difficulty": "سهل"}, {"id": "Q-002", "module": "EDU-01", "type": "mcq", "prompt": "لماذا لا تُنشر رواية حرق السفن كحقيقة ثابتة؟", "choices": ["لأنها محرمة شرعًا", "لأنها وردت في نقش معاصر", "لأنها تظهر في تقاليد متأخرة والبحث الحديث يشكك فيها", "لأن طارق لم يصل إلى الأندلس"], "correct": 2, "explanation": "المشكلة مصدرية: شهرة الرواية لا تعوض تأخر تقاليدها وضعف ثبوتها.", "claim": "CLM-002", "difficulty": "سهل"}, {"id": "Q-003", "module": "EDU-01", "type": "mcq", "prompt": "ما وظيفة Source Genealogy؟", "choices": ["رسم أنساب الأسر فقط", "تتبع اعتماد الروايات والنصوص على مصادر أقدم", "تحديد الإحداثيات", "حساب أسعار العملات"], "correct": 1, "explanation": "الهدف معرفة طبقة المصدر ومسافة الخبر عن الحدث، وعدم معاملة النص المتأخر كشاهد عيان.", "claim": "CLM-018", "difficulty": "متوسط"}, {"id": "Q-020", "module": "EDU-01", "type": "mcq", "prompt": "لماذا لا تعرض المنصة رقمًا واحدًا لعدد جيش طارق؟", "choices": ["لأن الرقم سري", "لأن ابن عبد الحكم وابن الأبار يذكران 1700 والطبري والرازي 12000، ولا ترجيح بعد", "لأن الجيش لم يُحصَ", "لأن الرقم في مصدر لاتيني فقط"], "correct": 1, "explanation": "الإسناد مسجل «متعارضًا»: ابن عبد الحكم يذكر ألفًا وسبعمائة ويردّ رواية اثني عشر ألفًا، والطبري والرازي يذكران اثني عشر ألفًا؛ والقاعدة أن يُذكر الخلاف لا أن يُختار رقم بصمت.", "claim": "CLM-FTH-01", "difficulty": "متوسط"}, {"id": "Q-004", "module": "EDU-02", "type": "mcq", "prompt": "ما الذي يميز شقندة كمصدر لفهم قرطبة المبكرة؟", "choices": ["قصائد فقط", "حفر واسع مؤرخ 750–818م", "خريطة عثمانية", "مخطوط طبخ"], "correct": 1, "explanation": "الحفر الواسع يقدم سجلًا مباشرًا للعمران والثقافة المادية والحياة اليومية قبل 818م.", "claim": "RUR-CLM04", "difficulty": "سهل"}, {"id": "Q-005", "module": "EDU-02", "type": "mcq", "prompt": "متى أعلن عبد الرحمن الثالث الخلافة وفق Claim المتحقق؟", "choices": ["711م", "756م", "929م", "1031م"], "correct": 2, "explanation": "الـClaim canonical يثبت الإعلان في 16 يناير 929م.", "claim": "CLM-001", "difficulty": "سهل"}, {"id": "Q-006", "module": "EDU-02", "type": "mcq", "prompt": "مدينة الزهراء في نموذج الأطلس تُقرأ أساسًا بوصفها:", "choices": ["ميناء تجاري فقط", "مدينة جديدة للخلافة ذات بنية حضرية", "مقبرة ريفية", "مدرسة ترجمة"], "correct": 1, "explanation": "UNESCO تصفها كمدينة جديدة للخلافة مع طرق ومياه ومبانٍ وأشياء يومية.", "claim": "ATLAS-CLM01", "difficulty": "سهل"}, {"id": "Q-007", "module": "EDU-03", "type": "mcq", "prompt": "ما تسلسل بَجّانة الأثري المهم في هذه الوحدة؟", "choices": ["قصر ثم ميناء", "فرن خزف مزجج ثم حي إسلامي", "مقبرة ثم كنيسة", "سد ثم منجم"], "correct": 1, "explanation": "الحفريات توثق مركز إنتاج خزف مزجج ثم حيًا بمساكن وشوارع ومحلات وورش.", "claim": "ARC-CLM04", "difficulty": "متوسط"}, {"id": "Q-008", "module": "EDU-03", "type": "mcq", "prompt": "لماذا لا تمثل كتب الطبخ كل المجتمع تلقائيًا؟", "choices": ["لأنها بلا لغة", "لأنها نصوص قد تعكس بيئات وطبقات محددة وتحتاج مقارنة بأدلة أخرى", "لأنها كلها حديثة", "لأنها لا تحتوي وصفات"], "correct": 1, "explanation": "المصدر النصي مهم، لكن تحويله إلى وصف شامل لكل السكان يتجاوز دلالته.", "claim": "ARC-CLM07", "difficulty": "متوسط"}, {"id": "Q-009", "module": "EDU-04", "type": "mcq", "prompt": "أي عبارة أقرب لقاعدة التحرير في موضوع convivencia؟", "choices": ["تسامح كامل دائم", "صراع ديني دائم", "علاقات متغيرة تجمع التعاون والتوتر والتراتبية بحسب السياق", "لا توجد جماعات دينية"], "correct": 2, "explanation": "المشروع يرفض السردية الأحادية في الاتجاهين ويطلب التفكيك زمانيًا ومكانيًا.", "claim": "SOC-CLM01", "difficulty": "سهل"}, {"id": "Q-010", "module": "EDU-04", "type": "mcq", "prompt": "هل يكفي الأسلوب الفني وحده لنسبة قطعة إلى هوية يهودية؟", "choices": ["نعم دائمًا", "لا؛ يلزم نقش أو سياق أو دليل إضافي", "فقط إذا كانت من القرن 10", "فقط إذا كانت ذهبية"], "correct": 1, "explanation": "الثقافة المادية اليومية قد تتشارك أشكالًا وتقنيات بين الجماعات.", "claim": "SOC-CLM04", "difficulty": "سهل"}, {"id": "Q-011", "module": "EDU-05", "type": "mcq", "prompt": "كيف نمثل انتقال المعرفة من الأندلس إلى المشرق؟", "choices": ["كخط سفر دقيق دون مصادر", "كمسارات أشخاص/أعمال موثقة مع تمييز ما نعرفه عما نفترضه", "كحدود سياسية", "كقائمة مدن بلا مصادر"], "correct": 1, "explanation": "الخطوط التعليمية لا تصبح طريق سفر تاريخيًا إلا إذا توفرت أدلة على المحطات والمسار.", "claim": "ARC-CLM09", "difficulty": "متوسط"}, {"id": "Q-012", "module": "EDU-05", "type": "mcq", "prompt": "ما الذي يوضحه خزف مانيسس في المشروع؟", "choices": ["توقف كل التقنيات بعد تغير السلطة", "استمرار تقنيات فنية أندلسية/نصرية في بيئة سياسية لاحقة", "أنه موقع في دمشق", "أنه عملة"], "correct": 1, "explanation": "الاستمرار التقني لا يطابق دائمًا حدود الدولة السياسية.", "claim": "SOC-CLM10", "difficulty": "متوسط"}, {"id": "Q-013", "module": "EDU-06", "type": "mcq", "prompt": "ماذا كانت الجيرالدا أصلًا؟", "choices": ["برجًا رومانيًا", "مئذنة مسجد", "حصنًا بحريًا", "مخزنًا"], "correct": 1, "explanation": "تصف UNESCO الجيرالدا بأنها المئذنة السابقة للمسجد وتحفة من العمارة الموحدية.", "claim": "ATLAS-CLM04", "difficulty": "سهل"}, {"id": "Q-014", "module": "EDU-06", "type": "mcq", "prompt": "ما تاريخ النواة الأصلية للقصر وفق UNESCO؟", "choices": ["القرن 8", "القرن 10", "القرن 13 فقط", "القرن 16"], "correct": 1, "explanation": "النواة الأصلية للقصر شُيدت في القرن العاشر مقرًا للحاكم المسلم.", "claim": "ATLAS-CLM04", "difficulty": "سهل"}, {"id": "Q-015", "module": "EDU-06", "type": "mcq", "prompt": "ما القاعدة المنهجية عند رؤية عنصر أندلسي باقٍ بعد تغير السلطة؟", "choices": ["نفترض بقاء الوظيفة والسياسة كما هي", "نميز بين بقاء العنصر وتغير الوظيفة والسياق", "نهمل العنصر", "ننسبه تلقائيًا للعصر المتأخر فقط"], "correct": 1, "explanation": "الاستمرار المادي يمكن أن يترافق مع تحول في الوظيفة والمعنى والسياق السياسي.", "claim": "ATLAS-CLM04", "difficulty": "متوسط"}, {"id": "Q-016", "module": "EDU-07", "type": "mcq", "prompt": "لمن كان والي الأندلس تابعًا في عصر الولاة؟", "choices": ["للخليفة العباسي ببغداد", "لوالي إفريقية الذي يتبع والي مصر، مع تعيين مباشر أحيانًا من الخليفة", "لأمير قرطبة", "لملك القوط"], "correct": 1, "explanation": "الادعاء الموثق يصف الأندلس ولايةً تابعة لوالي إفريقية التابع لوالي مصر، وأن الخليفة عيّن بعض الولاة مباشرة كالسمح.", "claim": "CLM-WUL-01", "difficulty": "سهل"}, {"id": "Q-017", "module": "EDU-07", "type": "mcq", "prompt": "بأي لقب خوطب حكام الإمارة الأموية قبل سنة 316هـ؟", "choices": ["الخليفة", "أمير المؤمنين", "الأمير", "السلطان"], "correct": 2, "explanation": "حكام الإمارة خوطبوا بـ«الأمير» ولم يتسمّوا بالخلافة ولا بإمرة المؤمنين حتى تسمّى عبد الرحمن بن محمد بأمير المؤمنين سنة 316هـ.", "claim": "CLM-EMR-02", "difficulty": "سهل"}, {"id": "Q-018", "module": "EDU-07", "type": "mcq", "prompt": "متى أمر عبد الرحمن الناصر أن يُخاطَب بأمير المؤمنين؟", "choices": ["سنة 138هـ عند بيعته", "في مستهل ذي الحجة 316هـ (نحو يناير 929م)", "سنة 325هـ عند بناء الزهراء", "سنة 399هـ عند بداية الفتنة"], "correct": 1, "explanation": "الشاهد يضع الإعلان في مستهل ذي الحجة 316هـ، والتحويل إلى الميلادي تقريبي بالحساب الجدولي.", "claim": "CLM-CAL-01", "difficulty": "متوسط"}, {"id": "Q-019", "module": "EDU-07", "type": "mcq", "prompt": "لماذا تعرض المنصة سنة مقتل عبد العزيز بن موسى بروايتين (97 و98هـ)؟", "choices": ["لأن المحقق أخطأ في الطباعة", "لأن المصادر اختلفت، والقاعدة أن يُذكر الخلاف لا أن يُختار رقم بصمت", "لأن التقويم الهجري لا يمكن تحويله", "لأن الحدث لم يقع"], "correct": 1, "explanation": "القاعدة الثامنة في منهج المنصة: عند اختلاف المصادر يُذكر الخلاف ولا يُختار رقم بصمت.", "claim": "CLM-WUL-01", "difficulty": "متوسط"}, {"id": "Q-021", "module": "EDU-07", "type": "mcq", "prompt": "ما الذي تتفق عليه المصادر في نهاية عقبة بن الحجاج، وما الذي تختلف فيه؟", "choices": ["تتفق على أنه قُتل غازيًا ولا خلاف", "تتفق على أن ولايته انتهت نحو 121هـ وتختلف هل قُتل غازيًا أم خُلع أم توفي", "تتفق على أنه خُلع سنة 116هـ", "لا تذكره المصادر أصلًا"], "correct": 1, "explanation": "ابن عذاري يورد رواية القتل في أرض الإفرنج ورواية الخلع ورواية الوفاة عن ابن القطان، وابن الأثير يذكر الوفاة ثم «قيل بل ثار به أهل الأندلس فخلعوه»؛ فالإسناد يثبت الخلاف ولا يحسمه.", "claim": "CLM-GOV-02", "difficulty": "متوسط"}, {"id": "Q-022", "module": "EDU-07", "type": "mcq", "prompt": "أي أمير بويع في المحلة على بربشتر في اليوم الذي مات فيه أخوه؟", "choices": ["هشام بن عبد الرحمن", "الحكم بن هشام", "عبد الله بن محمد", "عبد الرحمن الأوسط"], "correct": 2, "explanation": "يذكر ابن عذاري أن عبد الله بن محمد بويع يوم موت أخيه المنذر في المحلة على بربشتر في النصف من صفر 275هـ، ثم استتم البيعة بقرطبة.", "claim": "CLM-AMR-02", "difficulty": "سهل"}, {"id": "Q-023", "module": "EDU-07", "type": "mcq", "prompt": "من الذي قام على هشام المؤيد فخلعه في جمادى الآخرة 399هـ وتلقب بالمهدي؟", "choices": ["سليمان بن الحكم المستعين", "محمد بن هشام بن عبد الجبار", "علي بن حمود", "عبد الرحمن المرتضى"], "correct": 1, "explanation": "يذكر ابن حزم أن محمد بن هشام بن عبد الجبار قام على هشام بن الحكم في جمادى الآخرة 399هـ فخلعه وتسمى بالمهدي، ثم قام عليه سليمان بن الحكم مع البربر في شوال من السنة نفسها.", "claim": "CLM-CAL-04", "difficulty": "متوسط"}, {"id": "Q-024", "module": "EDU-07", "type": "mcq", "prompt": "في أي سنة سقطت طليطلة في يد الأذفونش بحسب ابن بسام والذهبي؟", "choices": ["456هـ", "478هـ", "484هـ", "503هـ"], "correct": 1, "explanation": "يقول ابن بسام المعاصر للحدث: «بحصول مدينة طليطلة في أيدي النصارى، وذلك في سنة ثمان وسبعين»، ويوافقه الذهبي وابن الأثير في موضع، وجعلها ابن الأثير في موضع آخر سنة 477هـ.", "claim": "CLM-TAI-02", "difficulty": "متوسط"}, {"id": "Q-025", "module": "EDU-08", "type": "mcq", "prompt": "لماذا سُميت الأندلس «جزيرة» عند الحميري؟", "choices": ["لأنها محاطة بالماء من كل جهة", "لأنها مثلثة الشكل يحيط بها البحر من ثلاث جهات", "لأن الزقاق يفصلها عن أوروبا", "لأنها في الإقليم الخامس"], "correct": 1, "explanation": "يقول الحميري: «وسميت جزيرة الأندلس جزيرة لأنها شكل مثلث»، ويحيط بها البحر الشامي والمظلم وبحر الروم من جهاتها الثلاث.", "claim": "CLM-GEO-02", "difficulty": "سهل"}, {"id": "Q-026", "module": "EDU-08", "type": "mcq", "prompt": "أي المدن الأربع عدّها الحميري قواعد ملوك الأعاجم قبل الفتح؟", "choices": ["إشبيلية وماردة وقرطبة وطليطلة", "غرناطة ومالقة والمرية ومرسية", "سرقسطة وبلنسية ودانية وطرطوشة", "بطليوس ولشبونة وشنترين وباجة"], "correct": 0, "explanation": "في مادة إشبيلية من الروض المعطار: «يتداولون بمسكنهم أربعة من مدن الأندلس: اشبيلية وماردة وقرطبة وطليطلة».", "claim": "CLM-GEO-03", "difficulty": "سهل"}, {"id": "Q-027", "module": "EDU-08", "type": "mcq", "prompt": "كم عرض الزقاق عند أضيقه؟", "choices": ["ثلاثة أميال باتفاق المصادر", "اثنا عشر ميلًا باتفاق المصادر", "مختلف فيه: ثلاثة أو اثنا عشر أو ثمانية عشر ميلًا", "لم يذكره أحد من القدماء"], "correct": 2, "explanation": "نص الروض المعطار يقول ثلاثة أميال، وابن حزم يقول اثنا عشر ميلًا بين سبتة والجزيرة الخضراء، ونسخة بروفنسال ثمانية عشر؛ والمنصة تعرض الخلاف ولا ترجّح.", "claim": "CLM-GEO-02", "difficulty": "متوسط"}, {"id": "Q-028", "module": "EDU-09", "type": "mcq", "prompt": "متى توفي أمير المسلمين يوسف بن تاشفين؟", "choices": ["484هـ", "500هـ", "537هـ", "558هـ"], "correct": 1, "explanation": "نص ابن الأثير والذهبي: توفي سنة 500هـ وملك بعده ابنه علي. أما 484هـ فسنة ضم الطوائف، و537هـ وفاة علي، و558هـ وفاة عبد المؤمن.", "claim": "CLM-MRB-01", "difficulty": "سهل"}, {"id": "Q-029", "module": "EDU-09", "type": "mcq", "prompt": "في أي يوم كانت وقعة الأرك سنة 591هـ؟", "choices": ["الأربعاء 3 شعبان باتفاق المصادر", "الأربعاء 9 شعبان باتفاق المصادر", "مختلف فيه: 3 شعبان عند المراكشي و9 شعبان عند ابن الأبار", "لم يذكره أحد من المؤرخين"], "correct": 2, "explanation": "المراكشي في المعجب يجعلها الأربعاء الثالث من شعبان، وابن الأبار في التكملة يجعلها الأربعاء التاسع منه؛ والمنصة تعرض الخلاف ولا ترجّح.", "claim": "CLM-MWH-02", "difficulty": "متوسط"}, {"id": "Q-030", "module": "EDU-09", "type": "mcq", "prompt": "ما أكبر أسباب هزيمة العقاب عند عبد الواحد المراكشي؟", "choices": ["قلة عدد المسلمين", "اختلاف قلوب الموحدين لتأخر العطاء", "خيانة ابن هود", "شدة البرد وفيضان النهر"], "correct": 1, "explanation": "نص المعجب: «وأكبر أسباب هذه الهزيمة اختلاف قلوب الموحدين»، وفسّره بتأخر العطاء الذي كانوا يأخذونه كل أربعة أشهر.", "claim": "CLM-MWH-02", "difficulty": "متوسط"}, {"id": "Q-031", "module": "EDU-09", "type": "mcq", "prompt": "أين بويع محمد بن يوسف بن نصر (ابن الأحمر) سنة 629هـ؟", "choices": ["غرناطة", "أرجونة", "جيان", "إشبيلية"], "correct": 1, "explanation": "الذهبي والإحاطة: بويع بأرجونة، وهي بليدة قرب قرطبة، ثم تملك جيان؛ ولم يدخل غرناطة إلا سنة 635هـ.", "claim": "CLM-NSR-01", "difficulty": "سهل"}, {"id": "Q-032", "module": "EDU-10", "type": "mcq", "prompt": "متى انقطعت الدعوة الأموية من قرطبة فبدأ عصر الطوائف؟", "choices": ["422هـ", "478هـ", "484هـ", "567هـ"], "correct": 0, "explanation": "بعد خلع هشام المعتد سنة 422هـ استولى ابن جهور على قرطبة واقتسم رؤساء الأطراف الأندلس؛ أما 478هـ فسقوط طليطلة، و484هـ نهاية الطوائف الأولى.", "claim": "CLM-TAI-01", "difficulty": "سهل"}, {"id": "Q-033", "module": "EDU-10", "type": "mcq", "prompt": "في أي سنة سقطت طليطلة في يد الأذفونش؟", "choices": ["467هـ", "478هـ (وعند ابن الأثير في موضع 477هـ)", "484هـ", "487هـ"], "correct": 1, "explanation": "سقطت طليطلة سنة 478هـ عند ابن بسام والذهبي وابن الأثير في موضع، و477هـ عند ابن الأثير في موضع آخر؛ والمنصة تعرض الخلاف.", "claim": "CLM-TAI-02", "difficulty": "متوسط"}, {"id": "Q-034", "module": "EDU-10", "type": "mcq", "prompt": "من قام بشرق الأندلس (مرسية وبلنسية) وقاوم الموحدين حتى سنة 567هـ؟", "choices": ["المعتمد بن عباد", "محمد بن سعد بن مردنيش", "المأمون بن ذي النون", "يوسف بن تاشفين"], "correct": 1, "explanation": "ابن مردنيش خادم ابن عياض تملّك مرسية وبلنسية وتحالف مع الفرنج على الموحدين حتى مات 29 رجب 567هـ فسلّم بنوه البلاد لأبي يعقوب.", "claim": "CLM-TAI-03", "difficulty": "متوسط"}, {"id": "Q-035", "module": "EDU-10", "type": "mcq", "prompt": "ماذا جرى للطوائف الأولى سنة 484هـ؟", "choices": ["توحّدت تحت خلافة جديدة", "انقرضت وأخذ المرابطون إشبيلية وغرناطة والمرية", "استقلّت عن المغرب", "سقطت كلها في يد النصارى"], "correct": 1, "explanation": "في 484هـ أُخذت إشبيلية من المعتمد وحُبس بأغمات، ومُلكت غرناطة في رجب 484هـ وماتت المرية إلى المرابطين، فانقرضت دول الطوائف وصارت الأندلس ليوسف بن تاشفين.", "claim": "CLM-TAI-02", "difficulty": "سهل"}, {"id": "Q-036", "module": "EDU-11", "type": "mcq", "prompt": "أين بويع محمد الأول ابن الأحمر قبل أن يتّخذ عاصمته؟", "choices": ["قرطبة", "أرجونة", "إشبيلية", "مالقة"], "correct": 1, "explanation": "بويع بأرجونة سنة 629هـ ثم دخل غرناطة 635هـ فاتخذها عاصمة (ادعاء موثق من الإحاطة والذهبي).", "claim": "CLM-NSR-01", "difficulty": "سهل"}, {"id": "Q-037", "module": "EDU-11", "type": "mcq", "prompt": "من المنافس الذي هزمه ابن الأحمر ثلاث مرات، وكان هلاكه بالمرية 635هـ هو عام دخول غرناطة؟", "choices": ["ابن هود", "ابن مردنيش", "المعتمد بن عباد", "ابن قسي"], "correct": 0, "explanation": "محمد بن يوسف بن هود الجذامي: دعا لبني العباس واستولى على أكثر الأندلس، وهلك بالمرية 635هـ فخلا الجوّ لابن الأحمر (تاريخ الإسلام).", "claim": "CLM-NSR-01", "difficulty": "متوسط"}, {"id": "Q-038", "module": "EDU-11", "type": "mcq", "prompt": "بمَ تُفسِّر المصادر طول صمود مملكة غرناطة؟", "choices": ["بكثرة جيشها فقط", "بمنعة الجبال والحصون وسياسة المهادنة", "بتحالفها مع الموحدين", "باتساع أرضها"], "correct": 1, "explanation": "يُعزى الصمود إلى المنعة الجبلية والحصون والمهادنة؛ وهي رواية تُعرض بتنبيه «موثقة جزئيًا» لأنها استنتاج لا نصّ مؤرَّخ صريح.", "claim": "CLM-NSR-01", "difficulty": "متوسط"}, {"id": "Q-039", "module": "EDU-11", "type": "mcq", "prompt": "ما الذي يجمع سلاطين الأواسط الأربعة (محمد الثالث ونصر وإسماعيل الأول ومحمد الرابع)؟", "choices": ["ماتوا جميعًا على فُرُشهم", "انتهى حكم كلٍّ منهم بخلعٍ أو اغتيال", "تنازلوا طوعًا", "حكموا معًا في آنٍ واحد"], "correct": 1, "explanation": "محمد الثالث ونصر خُلعا، وإسماعيل ومحمد الرابع قُتلا؛ اضطرابٌ داخلي لم يُسقط الدولة (الإحاطة).", "claim": "CLM-NSR-01", "difficulty": "متوسط"}];
